1	/**
2	 * `nx release` is a powerful feature which spans many possible use cases. The possible variations
3	 * of configuration are therefore quite complex, particularly when you consider release groups.
4	 *
5	 * We want to provide the best possible DX for users so that they can harness the power of `nx release`
6	 * most effectively, therefore we need to both provide sensible defaults for common scenarios (to avoid
7	 * verbose nx.json files wherever possible), and proactively handle potential sources of config issues
8	 * in more complex use-cases.
9	 *
10	 * This file is the source of truth for all `nx release` configuration reconciliation, including sensible
11	 * defaults and user overrides, as well as handling common errors, up front to produce a single, consistent,
12	 * and easy to consume config object for all the `nx release` command implementations.
13	 */
14	import { join, relative } from 'node:path';
15	import { URL } from 'node:url';
16	import {
17	  NxJsonConfiguration,
18	  NxReleaseChangelogConfiguration,
19	} from '../../../config/nx-json';
20	import { ProjectFileMap, ProjectGraph } from '../../../config/project-graph';
21	import { readJsonFile } from '../../../utils/fileutils';
22	import { findMatchingProjects } from '../../../utils/find-matching-projects';
23	import { output } from '../../../utils/output';
24	import { PackageJson } from '../../../utils/package-json';
25	import { workspaceRoot } from '../../../utils/workspace-root';
26	import { normalizePath } from '../../../utils/path';
27	import { resolveChangelogRenderer } from '../utils/resolve-changelog-renderer';
28	import { resolveNxJsonConfigErrorMessage } from '../utils/resolve-nx-json-error-message';
29	import { DEFAULT_CONVENTIONAL_COMMITS_CONFIG } from './conventional-commits';
30	
31	type DeepRequired<T> = Required<{
32	  [K in keyof T]: T[K] extends Required<T[K]> ? T[K] : DeepRequired<T[K]>;
33	}>;
34	
35	type EnsureProjectsArray<T> = {
36	  [K in keyof T]: T[K] extends { projects: any }
37	    ? Omit<T[K], 'projects'> & { projects: string[] }
38	    : T[K];
39	};
40	
41	type RemoveTrueFromType<T> = T extends true ? never : T;
42	type RemoveTrueFromProperties<T, K extends keyof T> = {
43	  [P in keyof T]: P extends K ? RemoveTrueFromType<T[P]> : T[P];
44	};
45	type RemoveTrueFromPropertiesOnEach<T, K extends keyof T[keyof T]> = {
46	  [U in keyof T]: RemoveTrueFromProperties<T[U], K>;
47	};
48	type RemoveBooleanFromType<T> = T extends boolean ? never : T;
49	type RemoveBooleanFromProperties<T, K extends keyof T> = {
50	  [P in keyof T]: P extends K ? RemoveBooleanFromType<T[P]> : T[P];
51	};
52	type RemoveBooleanFromPropertiesOnEach<T, K extends keyof T[keyof T]> = {
53	  [U in keyof T]: RemoveBooleanFromProperties<T[U], K>;
54	};
55	
56	export const IMPLICIT_DEFAULT_RELEASE_GROUP = '__default__';
57	
58	/**
59	 * Our source of truth is a deeply required variant of the user-facing config interface, so that command
60	 * implementations can be sure that properties will exist and do not need to repeat the same checks over
61	 * and over again.
62	 *
63	 * We also normalize the projects property on release groups to always be an array of project names to make
64	 * it easier to work with (the user could be specifying a single string, and they can also use any valid matcher
65	 * pattern such as directories and globs).
66	 */
67	export type NxReleaseConfig = Omit<
68	  DeepRequired<
69	    NxJsonConfiguration['release'] & {
70	      groups: DeepRequired<
71	        RemoveTrueFromPropertiesOnEach<
72	          EnsureProjectsArray<NxJsonConfiguration['release']['groups']>,
73	          'changelog'
74	        >
75	      >;
76	      // Remove the true shorthand from the changelog config types, it will be normalized to a default object
77	      changelog: RemoveTrueFromProperties<
78	        DeepRequired<NxJsonConfiguration['release']['changelog']>,
79	        'workspaceChangelog' | 'projectChangelogs'
80	      >;
81	      // Remove the false shorthand from the conventionalCommits config types, it will be normalized to a semver bump of "none" and to be hidden on the changelog
82	      conventionalCommits: {
83	        types: RemoveBooleanFromPropertiesOnEach<
84	          DeepRequired<
85	            RemoveBooleanFromProperties<
86	              DeepRequired<
87	                NxJsonConfiguration['release']['conventionalCommits']['types']
88	              >,
89	              string
90	            >
91	          >,
92	          'changelog'
93	        >;
94	      };
95	    }
96	  >,
97	  // projects is just a shorthand for the default group's projects configuration, it does not exist in the final config
98	  'projects'
99	>;
100	
101	// We explicitly handle some possible errors in order to provide the best possible DX
102	export interface CreateNxReleaseConfigError {
103	  code:
104	    | 'PROJECTS_AND_GROUPS_DEFINED'
105	    | 'RELEASE_GROUP_MATCHES_NO_PROJECTS'
106	    | 'RELEASE_GROUP_RELEASE_TAG_PATTERN_VERSION_PLACEHOLDER_MISSING_OR_EXCESSIVE'
107	    | 'PROJECT_MATCHES_MULTIPLE_GROUPS'
108	    | 'CONVENTIONAL_COMMITS_SHORTHAND_MIXED_WITH_OVERLAPPING_GENERATOR_OPTIONS'
109	    | 'GLOBAL_GIT_CONFIG_MIXED_WITH_GRANULAR_GIT_CONFIG'
110	    | 'CANNOT_RESOLVE_CHANGELOG_RENDERER'
111	    | 'INVALID_CHANGELOG_CREATE_RELEASE_PROVIDER'
112	    | 'INVALID_CHANGELOG_CREATE_RELEASE_HOSTNAME'
113	    | 'INVALID_CHANGELOG_CREATE_RELEASE_API_BASE_URL';
114	  data: Record<string, string | string[]>;
115	}
116	
117	// Apply default configuration to any optional user configuration and handle known errors
118	export async function createNxReleaseConfig(
119	  projectGraph: ProjectGraph,
120	  projectFileMap: ProjectFileMap,
121	  userConfig: NxJsonConfiguration['release'] = {}
122	): Promise<{
123	  error: null | CreateNxReleaseConfigError;
124	  nxReleaseConfig: NxReleaseConfig | null;
125	}> {
126	  if (userConfig.projects && userConfig.groups) {
127	    return {
128	      error: {
129	        code: 'PROJECTS_AND_GROUPS_DEFINED',
