126	export interface NxReleaseGitConfiguration {
127	  /**
128	   * Whether or not to automatically commit the changes made by current command
129	   */
130	  commit?: boolean;
131	  /**
132	   * Custom git commit message to use when committing the changes made by this command {version} will be dynamically interpolated when performing fixed releases, interpolated tags will be appended to the commit body when performing independent releases.
133	   */
134	  commitMessage?: string;
135	  /**
136	   * Additional arguments (added after the --message argument, which may or may not be customized with --git-commit-message) to pass to the `git commit` command invoked behind the scenes. May be a string or array of strings.
137	   */
138	  commitArgs?: string | string[];
139	  /**
140	   * Whether or not to stage the changes made by this command. Always treated as true if commit is true.
141	   */
142	  stageChanges?: boolean;
143	  /**
144	   * Whether or not to automatically tag the changes made by this command
145	   */
146	  tag?: boolean;
147	  /**
148	   * Custom git tag message to use when tagging the changes made by this command. This defaults to be the same value as the tag itself.
149	   */
150	  tagMessage?: string;
151	  /**
152	   * Additional arguments to pass to the `git tag` command invoked behind the scenes. . May be a string or array of strings.
153	   */
154	  tagArgs?: string | string[];
155	}
156	
157	export interface NxReleaseConventionalCommitsConfiguration {
158	  types?: Record<
159	    string,
160	    /**
161	     * A map of commit types to their configuration.
162	     * If a type is set to 'true', then it will be enabled with the default 'semverBump' of 'patch' and will appear in the changelog.
163	     * If a type is set to 'false', then it will not trigger a version bump and will be hidden from the changelog.
164	     */
165	    | {
166	        /**
167	         * The semver bump to apply when a commit of this type is found.
168	         * If set to "none", the commit will be ignored for versioning purposes.
169	         */
170	        semverBump?: 'patch' | 'minor' | 'major' | 'none';
171	        /**
172	         * Configuration for the changelog section for commits of this type.
173	         * If set to 'true', then commits of this type will be included in the changelog with their default title for the type.
174	         * If set to 'false', then commits of this type will not be included in the changelog.
175	         */
176	        changelog?:
177	          | {
178	              title?: string;
179	              hidden?: boolean;
180	            }
181	          | boolean;
182	      }
183	    | boolean
184	  >;
185	}

